            ["Arrastra la línea con el dedo o el ratón: es más rápido que el teclado."] = ("Arraste a linha com o dedo ou o mouse: é mais rápido que o teclado.", "Fais glisser la ligne au doigt ou à la souris : c'est plus rapide que le clavier."),
            ["Las Sombras duermen de día. Sobre su piedra se puede caminar... casi."] = ("As Sombras dormem de dia. Dá para andar sobre a pedra delas... quase.", "Les Ombres dorment le jour. On peut marcher sur leur pierre... presque."),
            ["El lago es agua de día y hielo de noche."] = ("O lago é água de dia e gelo à noite.", "Le lac est de l'eau le jour et de la glace la nuit."),
            ["Las plataformas con engranaje solo se mueven al sol."] = ("As plataformas com engrenagem só se movem ao sol.", "Les plateformes à engrenage ne bougent qu'au soleil."),
            ["Donde bailan las luciérnagas hay un camino escondido."] = ("Onde os vaga-lumes dançam há um caminho escondido.", "Là où dansent les lucioles, il y a un chemin caché."),
            ["Las medallas de Luna son secretas. Y muy difíciles."] = ("As medalhas de Lua são secretas. E muito difíceis.", "Les médailles de Lune sont secrètes. Et très difficiles."),
            ["Con todos los fragmentos de un capítulo se abre algo en el mapa."] = ("Com todos os fragmentos de um capítulo, algo se abre no mapa.", "Avec tous les fragments d'un chapitre, quelque chose s'ouvre sur la carte."),
            ["¿Te atascas? Prueba el modo asistido en Opciones → Controles."] = ("Empacou? Tente o modo assistido em Opções → Controles.", "Tu bloques ? Essaie le mode assisté dans Options → Commandes."),
