            ["Ayudaste al día: el sol salió un poco antes ese año."] = ("Você ajudou o dia: o sol nasceu um pouco mais cedo naquele ano.", "Tu as aidé le jour : le soleil s'est levé un peu plus tôt cette année-là."),
            ["Ayudaste a la noche: las luciérnagas no olvidaron tu nombre."] = ("Você ajudou a noite: os vaga-lumes nunca esqueceram seu nome.", "Tu as aidé la nuit : les lucioles n'ont jamais oublié ton nom."),
            ["En el bosque, el día y la noche discuten.\n¿A quién ayudas?"] = ("Na floresta, o dia e a noite discutem.\nQuem você ajuda?", "Dans la forêt, le jour et la nuit se disputent.\nQui aides-tu ?"),
            ["☀ Al día"] = ("☀ O dia", "☀ Le jour"),
            ["☾ A la noche"] = ("☾ A noite", "☾ La nuit"),
            ["Con cada trozo de luna y cada página del diario, Lumi entendió\nque el día y la noche nunca estuvieron peleados: se estaban buscando."] = ("Com cada pedaço de lua e cada página do diário, Lumi entendeu\nque o dia e a noite nunca estiveram brigados: estavam se procurando.", "Avec chaque morceau de lune et chaque page du journal, Lumi a compris\nque le jour et la nuit ne s'étaient jamais disputés : ils se cherchaient."),
            ["“Las hojas recordaban el verano, y la noche les susurraba que todo cambia.”"] = ("“As folhas lembravam o verão, e a noite sussurrava que tudo muda.”", "« Les feuilles se souvenaient de l'été, et la nuit leur murmurait que tout change. »"),
            ["“Arriba, donde la nieve no se derrite, la luna esperaba su último trozo.”"] = ("“Lá em cima, onde a neve não derrete, a lua esperava seu último pedaço.”", "« Là-haut, où la neige ne fond jamais, la lune attendait son dernier morceau. »"),
            ["“Había una vez una luna partida en dos, y una línea que separaba el día de la noche.”"] = ("“Era uma vez uma lua partida em dois, e uma linha que separava o dia da noite.”", "« Il était une fois une lune coupée en deux, et une ligne qui séparait le jour de la nuit. »"),
            ["Lumi dejó atrás la pradera."] = ("Lumi deixou a pradaria para trás.", "Lumi a laissé la prairie derrière elle."),
            ["Los árboles se volvieron rojos\ny el viento olía a otoño.\n\nEn algún lugar del bosque\nbrillaba otro trozo de luna."] = ("As árvores ficaram vermelhas\ne o vento cheirava a outono.\n\nEm algum lugar da floresta\nbrilhava outro pedaço de lua.", "Les arbres sont devenus rouges\net le vent sentait l'automne.\n\nQuelque part dans la forêt\nbrillait un autre morceau de lune."),
            ["Lumi dejó atrás el bosque."] = ("Lumi deixou a floresta para trás.", "Lumi a laissé la forêt derrière elle."),
            ["Arriba, en la Cumbre Helada,\nel último trozo de luna\nesperaba bajo la nieve.\n\nHacía frío. Mucho frío."] = ("Lá em cima, no Cume Gelado,\no último pedaço de lua\nesperava sob a neve.\n\nFazia frio. Muito frio.", "Là-haut, sur le Sommet glacé,\nle dernier morceau de lune\nattendait sous la neige.\n\nIl faisait froid. Très froid."),
