            ["La noche te sigue"] = ("A noite te segue", "La nuit te suit"),
            ["Hubo un tiempo en que el día y la noche compartían el mismo cielo."] = ("Houve um tempo em que o dia e a noite dividiam o mesmo céu.", "Il fut un temps où le jour et la nuit partageaient le même ciel."),
            ["Pero una noche, la luna se rompió en mil pedazos…"] = ("Mas uma noite, a lua se partiu em mil pedaços…", "Mais une nuit, la lune s'est brisée en mille morceaux…"),
            ["…y una grieta de luz partió el mundo en dos."] = ("…e uma fenda de luz partiu o mundo em dois.", "…et une fissure de lumière a coupé le monde en deux."),
            ["Lumi decidió reunir los fragmentos. Solo tenía un farol… y la línea."] = ("Lumi decidiu juntar os fragmentos. Só tinha uma lanterna… e a linha.", "Lumi a décidé de réunir les fragments. Elle n'avait qu'une lanterne… et la ligne."),
            ["De noche sube la marea; de día sopla el viento.\nBusca el equilibrio."] = ("À noite a maré sobe; de dia sopra o vento.\nProcure o equilíbrio.", "La nuit, la marée monte ; le jour, le vent souffle.\nTrouve l'équilibre."),
            ["Cada llave solo se coge en su mundo y abre su puerta.\nLa caja se lleva: suéltala con ↓."] = ("Cada chave só se pega no seu mundo e abre a sua porta.\nA caixa pode ser levada: solte com ↓.", "Chaque clé ne se prend que dans son monde et ouvre sa porte.\nLa caisse se porte : lâche-la avec ↓."),
            ["Solo ves lo que ilumina tu farol.\nY algo corre hacia la línea..."] = ("Você só vê o que sua lanterna ilumina.\nE algo corre em direção à linha...", "Tu ne vois que ce qu'éclaire ta lanterne.\nEt quelque chose court vers la ligne..."),
            ["Las tablas doradas van al ritmo de la música. Salta a tiempo.\nArriba, el camino difícil."] = ("As tábuas douradas seguem o ritmo da música. Pule no tempo certo.\nLá em cima, o caminho difícil.", "Les planches dorées suivent le rythme de la musique. Saute en mesure.\nEn haut, le chemin difficile."),
            ["La línea se ha curvado: dentro del arco es de noche.\nLas puertas moradas se abren cuando la línea pasa por ellas."] = ("A linha se curvou: dentro do arco é noite.\nAs portas roxas se abrem quando a linha passa por elas.", "La ligne s'est courbée : dans l'arc, il fait nuit.\nLes portes violettes s'ouvrent quand la ligne les traverse."),
            ["De noche, las sombras se pisan.\nAquí la línea separa el otoño del invierno."] = ("À noite, dá para pisar nas sombras.\nAqui a linha separa o outono do inverno.", "La nuit, on peut marcher sur les ombres.\nIci, la ligne sépare l'automne de l'hiver."),
            ["Otra subida con la línea tumbada, al revés que la primera."] = ("Outra subida com a linha deitada, ao contrário da primeira.", "Une autre montée avec la ligne couchée, à l'inverse de la première."),
            ["Las calles brillan con la aurora. Los puentes de luz solo existen de día."] = ("As ruas brilham com a aurora. As pontes de luz só existem de dia.", "Les rues brillent sous l'aurore. Les ponts de lumière n'existent que le jour."),
            ["Salta de tejado en tejado. De noche, las luciérnagas te hacen de suelo."] = ("Pule de telhado em telhado. À noite, os vaga-lumes viram chão.", "Saute de toit en toit. La nuit, les lucioles te servent de sol."),
            ["Las puertas de la avenida se abren cuando la línea las cruza."] = ("As portas da avenida se abrem quando a linha as cruza.", "Les portes de l'avenue s'ouvrent quand la ligne les traverse."),
            ["Bajo el mar la luz llega de lado. De noche, el agua se vuelve hielo."] = ("Sob o mar a luz chega de lado. À noite, a água vira gelo.", "Sous la mer, la lumière arrive de côté. La nuit, l'eau se change en glace."),
            ["Las corrientes de día te suben. Cuidado con las abejas del arrecife."] = ("As correntes de dia te levam para cima. Cuidado com as abelhas do recife.", "Les courants du jour te font monter. Attention aux abeilles du récif."),
            ["En lo más hondo, la marea sube de noche. Sube por los pilares a tiempo."] = ("No mais fundo, a maré sobe à noite. Suba pelos pilares a tempo.", "Tout au fond, la marée monte la nuit. Grimpe aux piliers à temps."),
            ["Práctica: una cosa a cada lado de la línea, DOS líneas a la vez\ny la burbuja de noche del farol (L) donde bailan las luciérnagas."] = ("Prática: uma coisa de cada lado da linha, DUAS linhas ao mesmo tempo\ne a bolha de noite da lanterna (L) onde dançam os vaga-lumes.", "Entraînement : une chose de chaque côté de la ligne, DEUX lignes à la fois\net la bulle de nuit de la lanterne (L) là où dansent les lucioles."),
            ["Lo naranja solo existe pegado a la línea: llévala contigo al subir.\nLos brotes crecen al sol."] = ("O laranja só existe colado à linha: leve-a com você ao subir.\nOs brotos crescem ao sol.", "L'orange n'existe que collé à la ligne : emmène-la en montant.\nLes pousses grandissent au soleil."),
            ["Un espejo al sol refleja el día lejos de la línea.\nDe noche, acércale tu farol."] = ("Um espelho ao sol reflete o dia longe da linha.\nÀ noite, aproxime sua lanterna.", "Un miroir au soleil renvoie le jour loin de la ligne.\nLa nuit, approche ta lanterne."),
            ["La línea pesa: si la sueltas, cae.\nLas palancas cambian el día y la noche de lado un momento."] = ("A linha pesa: se você a soltar, ela cai.\nAs alavancas trocam o dia e a noite de lado por um momento.", "La ligne pèse : si tu la lâches, elle tombe.\nLes leviers échangent le jour et la nuit un instant."),
            ["La noche avanza sola por detrás. ¡No te pares!"] = ("A noite avança sozinha por trás. Não pare!", "La nuit avance toute seule derrière toi. Ne t'arrête pas !"),
